### Task 7: Faces as SVG

**Files:**

- Create: `streamdeck/src/face.ts`
- Test: `streamdeck/src/face.test.ts`

**Interfaces:**

- Consumes: `Face`, `Tone` from Task 6.
- Produces: `faceImage(face: Face): string` — a `data:image/svg+xml;base64,…` URI, 144×144.

- [ ] **Step 1: Write the failing test**

```ts
import { describe, expect, it } from "vitest";
import { faceImage } from "./face.ts";

describe("faceImage", () => {
  it("is a base64 svg data uri, never raw svg", () => {
    const uri = faceImage({ title: "Roll the Weather", tone: "live" });
    expect(uri.startsWith("data:image/svg+xml;base64,")).toBe(true);
    const svg = Buffer.from(uri.slice("data:image/svg+xml;base64,".length), "base64").toString("utf8");
    expect(svg).toContain("Roll the");
    expect(svg).toContain('viewBox="0 0 144 144"');
  });
  it("escapes what a pack might put in a label", () => {
    const svg = Buffer.from(faceImage({ title: "<Bowl> & \"Kiln\"", tone: "dim" }).split(",")[1]!, "base64").toString("utf8");
    expect(svg).not.toContain("<Bowl>");
    expect(svg).toContain("&lt;Bowl&gt; &amp; &quot;Kiln&quot;");
  });
  it("wraps a long label onto three lines and no more", () => {
    const svg = Buffer.from(faceImage({ title: "Name the bowl on the page please", tone: "refuse" }).split(",")[1]!, "base64").toString("utf8");
    expect((svg.match(/<tspan/g) ?? []).length).toBe(3);
    expect(svg).toContain("…");
  });
});
```

- [ ] **Step 2: Run test to verify it fails**

Run: `npx vitest run streamdeck/src/face.test.ts`
Expected: FAIL — cannot resolve `./face.ts`.

- [ ] **Step 3: Write the renderer**

```ts
import type { Face, Tone } from "./state.ts";

/**
 * A key face as SVG.
 *
 * SVG, because it needs no rasterizer and no native module in a package
 * the Marketplace installs; base64, because Stream Deck 7.5 on Windows
 * rejects a raw SVG string despite the documentation. 144 square is the
 * @2x size; the software scales it to any key.
 *
 * The palette is the app's own: celadon for a live key, kiln for a
 * refusal, the muted ink for a key with nothing to do. System sans, since
 * a font in an SVG would have to travel as base64 on every redraw.
 */
const TONE: Record<Tone, { ground: string; ink: string; edge: string }> = {
  live: { ground: "#1e2f27", ink: "#e7eae6", edge: "#8cc3a6" },
  dim: { ground: "#1b201d", ink: "#8d958f", edge: "#2f3733" },
  refuse: { ground: "#33211a", ink: "#e7eae6", edge: "#dd8f63" },
};

const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

/** Up to three lines of about twelve characters; the last one ends in an ellipsis if there was more. */
export function wrap(text: string, width = 12, lines = 3): string[] {
  const out: string[] = [];
  let line = "";
  for (const word of text.split(/\s+/).filter(Boolean)) {
    if (line && (line + " " + word).length > width) {
      out.push(line);
      line = word;
    } else line = line ? `${line} ${word}` : word;
    if (out.length === lines) break;
  }
  if (out.length < lines && line) out.push(line);
  if (out.length > lines || (out.length === lines && (line && !out.includes(line)))) {
    out.length = lines;
    out[lines - 1] = out[lines - 1]!.slice(0, width - 1) + "…";
  }
  return out;
}

export function faceImage(face: Face): string {
  const t = TONE[face.tone];
  const lines = wrap(face.title);
  const size = lines.length === 1 && face.title.length <= 6 ? 34 : 20;
  const top = 72 - ((lines.length - 1) * size * 1.15) / 2 + (face.when ? -8 : 0);
  const spans = lines.map((l, i) => `<tspan x="72" y="${(top + i * size * 1.15).toFixed(1)}">${esc(l)}</tspan>`).join("");
  const when = face.when ? `<text x="72" y="128" text-anchor="middle" font-size="12" fill="${t.edge}" font-family="ui-monospace, Menlo, Consolas, monospace">${esc(face.when.slice(0, 18))}</text>` : "";
  const svg =
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 144 144">` +
    `<rect width="144" height="144" rx="14" fill="${t.ground}"/>` +
    `<rect x="3" y="3" width="138" height="138" rx="12" fill="none" stroke="${t.edge}" stroke-width="3"/>` +
    `<text text-anchor="middle" dominant-baseline="middle" font-size="${size}" font-weight="600" fill="${t.ink}" font-family="system-ui, -apple-system, Segoe UI, sans-serif">${spans}</text>` +
    when +
    `</svg>`;
  return `data:image/svg+xml;base64,${Buffer.from(svg, "utf8").toString("base64")}`;
}
```

- [ ] **Step 4: Run the tests**

Run: `npx vitest run streamdeck/src/face.test.ts`
Expected: PASS. If the third test's `tspan` count is off by one, fix `wrap` — the test is the contract, three lines and an ellipsis.

- [ ] **Step 5: Commit**

```bash
npm run typecheck
git add streamdeck/src/face.ts streamdeck/src/face.test.ts
git commit -m "feat(deck): a key face is an svg with no rasterizer behind it"
```

